import traceback


def inner():
    return 1 / 0


try:
    inner()
except ZeroDivisionError:
    tb = traceback.format_exc()

print("ZeroDivisionError" in tb)
print("inner" in tb)

def average(nums):
    assert nums, "空列表没有平均值"
    return sum(nums) / len(nums)


print(average([1, 2, 3]))

try:
    average([])
except AssertionError as exc:
    print(type(exc).__name__, exc)

